SELECT FLT_NO FROM FLIGHT
 WHERE (DEP, FARE) IN (SELECT DEP, MIN(FARE) FROM FLIGHT GROUP BY DEP);

-- (나)
SELECT FLT_NO FROM FLIGHT
 WHERE FARE IN (SELECT MIN(FARE) FROM FLIGHT GROUP BY DEP);

